package com.mfrp.plens.service;
import com.mfrp.plens.dto.ProjectSubmissionRequest;import com.mfrp.plens.exception.ResourceNotFoundException;import com.mfrp.plens.model.*;import com.mfrp.plens.repository.ProjectSubmissionRepository;import com.mfrp.plens.service.evaluation.RuleBasedEvaluationService;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ProjectSubmissionService { private final ProjectSubmissionRepository repository;private final RuleBasedEvaluationService evaluator;public ProjectSubmissionService(ProjectSubmissionRepository repository,RuleBasedEvaluationService evaluator){this.repository=repository;this.evaluator=evaluator;}public List<ProjectSubmission> findAll(){return repository.findAll();}public ProjectSubmission create(ProjectSubmissionRequest request){ProjectSubmission s=ProjectSubmission.builder().podName(request.podName()).title(request.title()).problemStatement(request.problemStatement()).objectives(request.objectives()).technologyStack(request.technologyStack()).documentationLink(request.documentationLink()).build();s.setAlignmentScore(evaluator.alignment(s));s.setOverlapScore(evaluator.overlap(s,repository.findAll()));return repository.save(s);}public ProjectSubmission decide(Long id,DecisionStatus status){ProjectSubmission s=repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Submission not found: "+id));s.setDecisionStatus(status);return repository.save(s);} }
